/* ==================== Ключи хранения ==================== */
/* ==================== Панели поиска (Учёт/Склад/1С) ====================
   Разметка одинаковая для всех трёх вкладок — генерируем один раз вместо
   трёх копий в HTML. Должно выполниться раньше, чем что-либо ниже
   обратится к whSearchInput/caSearchClear и т.п. через getElementById. */
function searchBarHTML(prefix) {
  return `
    <span class="search-icon">🔍</span>
    <input type="text" id="${prefix}SearchInput" placeholder="Поиск" autocomplete="off" style="flex:1;">
    <button class="iconbtn clear" id="${prefix}SearchClear" title="Очистить поле">✕</button>
    <span class="search-count" id="${prefix}SearchCount"></span>
    <button class="iconbtn nav" id="${prefix}SearchPrev" title="Предыдущее совпадение">‹</button>
    <button class="iconbtn nav" id="${prefix}SearchNext" title="Следующее совпадение">›</button>
  `;
}
["wh", "ca", "oc"].forEach((prefix) => {
  const bar = document.getElementById(prefix + "SearchBar");
  if (bar) bar.innerHTML = searchBarHTML(prefix);
});

/* ==================== Страховка: переключение вкладок ====================
   Регистрируется в самом начале скрипта. Даже если ниже произойдёт ошибка
   загрузки, вкладки продолжат переключаться (функция switchTab всплывает
   благодаря hoisting объявлений функций). */
const suggestZones = [];               // { box, inputs[] } — закрываются кликом мимо
function registerSuggestZone(box, inputs) { if (box) suggestZones.push({ box, inputs }); }

let lastTabSwitch = 0;
function handleTabPress(e) {
  const btn = e.target && e.target.closest ? e.target.closest(".tab-btn") : null;
  if (!btn) return;
  const now = Date.now();
  if (now - lastTabSwitch < 400) return;   // click + pointerup на тачскрине
  lastTabSwitch = now;
  if (typeof switchTab === "function") switchTab(tabTargetFromId(btn.id));
}

/* Один обработчик на все глобальные реакции клика:
   переключение вкладок, снятие временной подсветки, закрытие подсказок. */
document.addEventListener("click", function (e) {
  handleTabPress(e);
  document.querySelectorAll(".row-flash").forEach((el) => el.classList.remove("row-flash"));
  suggestZones.forEach(({ box, inputs }) => {
    if (!box.contains(e.target) && inputs.indexOf(e.target) === -1) box.classList.remove("open");
  });
});
document.addEventListener("pointerup", handleTabPress);   // страховка для тачскрина

const DATA_BY_DATE_KEY = "potreblenie_data_by_date_v3";
const LAST_DATE_KEY = "potreblenie_last_date_v1";
const WAREHOUSE_KEY = "potreblenie_warehouse_v1";
const CLIPBOARD_KEY = "potreblenie_clipboard_day_v1";

const MONTHS_FULL_GEN = ["января","февраля","марта","апреля","мая","июня","июля","августа","сентября","октября","ноября","декабря"];

function todayStr() { return new Date().toISOString().slice(0, 10); }
function formatShort(dateStr) {
  if (!dateStr) return "—";
  const [y, m, d] = dateStr.split("-").map(Number);
  if (!y || !m || !d) return dateStr;
  return `${String(d).padStart(2,"0")}.${String(m).padStart(2,"0")}`;
}
function formatFull(dateStr) {
  if (!dateStr) return "";
  const [y, m, d] = dateStr.split("-").map(Number);
  if (!y || !m || !d) return dateStr;
  return `${d} ${MONTHS_FULL_GEN[m - 1]} ${y}`;
}
function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  }[c]));
}
/* Если код склеен из двух через "/", показываем вторым уровнем под первым */
function formatCodeDisplay(code) {
  const parts = escapeHtml(code).split("/").map((s) => s.trim()).filter(Boolean);
  if (parts.length <= 1) return escapeHtml(code);
  return `<span class="code-split">${parts.map((p) => `<span class="code-line">${p}</span>`).join("")}</span>`;
}

/* ==================== Загрузка/сохранение ==================== */
function loadDataByDate() {
  try {
    const raw = localStorage.getItem(DATA_BY_DATE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return (parsed && typeof parsed === "object") ? parsed : {};
  } catch (e) { return {}; }
}
function saveDataByDate() {
  try { localStorage.setItem(DATA_BY_DATE_KEY, JSON.stringify(dataByDate)); } catch (e) {}
  scheduleSync();
}
function loadWarehouse() {
  try {
    const raw = localStorage.getItem(WAREHOUSE_KEY);
    if (!raw) return JSON.parse(JSON.stringify(WAREHOUSE_SEED));
    const parsed = JSON.parse(raw);
    if (parsed && Array.isArray(parsed.parts) && Array.isArray(parsed.consumables)) return parsed;
    return JSON.parse(JSON.stringify(WAREHOUSE_SEED));
  } catch (e) { return JSON.parse(JSON.stringify(WAREHOUSE_SEED)); }
}
function saveWarehouse() {
  try { localStorage.setItem(WAREHOUSE_KEY, JSON.stringify(warehouse)); } catch (e) {}
  scheduleSync();
}
// Локально, без синхронизации — для чисто визуальных действий (сортировка),
// которые не должны считаться правкой данных и уходить на сервер.
function saveWarehouseLocalOnly() {
  try { localStorage.setItem(WAREHOUSE_KEY, JSON.stringify(warehouse)); } catch (e) {}
}
function loadClipboard() {
  try {
    const raw = localStorage.getItem(CLIPBOARD_KEY);
    if (!raw) return null;
    return JSON.parse(raw);
  } catch (e) { return null; }
}
function saveClipboard() {
  try { localStorage.setItem(CLIPBOARD_KEY, JSON.stringify(clipboardDay)); } catch (e) {}
}

let dataByDate = loadDataByDate();
let warehouse = loadWarehouse(); // { parts: [{code,name,qty}], consumables: [...] }
let clipboardDay = loadClipboard(); // { parts:[{name,code}], consumables:[...] } | null
// Дата при каждом открытии приложения — всегда сегодняшняя (а не та, на которой
// остановились в прошлый раз): открыли на следующий день — календарь сам на нём.
let currentDate = todayStr();

function entryFor(date) {
  if (!dataByDate[date]) {
    dataByDate[date] = { sections: { parts: [], consumables: [] }, counts: {}, checked: {} };
  }
  if (!dataByDate[date].checked) dataByDate[date].checked = {};
  if (!dataByDate[date].sections) dataByDate[date].sections = { parts: [], consumables: [] };
  return dataByDate[date];
}

let sections = entryFor(currentDate).sections;
let counts = entryFor(currentDate).counts;
let checked = entryFor(currentDate).checked;

function persistCurrent() {
  dataByDate[currentDate] = { sections, counts, checked };
  saveDataByDate();
}
// Локально, без синхронизации — используется при переключении даты
// (сохраняем то, что уже было введено, но само переключение — не правка).
function persistCurrentLocalOnly() {
  dataByDate[currentDate] = { sections, counts, checked };
  try { localStorage.setItem(DATA_BY_DATE_KEY, JSON.stringify(dataByDate)); } catch (e) {}
}

/* ==================== Общий механизм отмены/повтора (для всех 3 вкладок) ====================
   Раньше у «Учёта», «Склада» и «1С» было по три копии одного и того же:
   свой стек отмены, свой стек повтора, своя функция снимка состояния,
   своя привязка кнопок ↶/↷. Теперь это один универсальный конструктор —
   каждая вкладка просто передаёт «как снять снимок» и «как восстановить
   состояние из снимка» (там разная логика: разные глобальные переменные,
   разный рендер, разная подсветка изменившейся строки). */
function makeUndoRedo({ snapshotFn, restoreFn, undoBtnId, redoBtnId, limit }) {
  const undoStack = [];
  const redoStack = [];
  const undoBtn = document.getElementById(undoBtnId);
  const redoBtn = document.getElementById(redoBtnId);
  function updateButtons() {
    undoBtn.disabled = undoStack.length === 0;
    redoBtn.disabled = redoStack.length === 0;
  }
  function push() {
    undoStack.push(snapshotFn());
    if (undoStack.length > limit) undoStack.shift();
    redoStack.length = 0;
    updateButtons();
  }
  function undo() {
    if (undoStack.length === 0) return;
    redoStack.push(snapshotFn());
    restoreFn(undoStack.pop());
    updateButtons();
  }
  function redo() {
    if (redoStack.length === 0) return;
    undoStack.push(snapshotFn());
    restoreFn(redoStack.pop());
    updateButtons();
  }
  function reset() {
    undoStack.length = 0;
    redoStack.length = 0;
    updateButtons();
  }
  undoBtn.addEventListener("click", undo);
  redoBtn.addEventListener("click", redo);
  updateButtons();
  return { push, undo, redo, reset, updateButtons };
}

/* ==================== История (отмена/повтор) — вкладка «Учёт» ==================== */
const HISTORY_LIMIT = 50;
function snapshot() { return JSON.stringify({ sections, counts, checked }); }

/* ==================== Подсветка изменённой строки при отмене ====================
   Сравниваем состояние до и после отката и прыгаем к первой различающейся
   позиции, чтобы было видно, что именно изменилось. */
function firstDiffIndex(a, b) {
  a = a || []; b = b || [];
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (JSON.stringify(a[i]) !== JSON.stringify(b[i])) return i;
  }
  return -1;
}

/* Ищет, в каком разделе и на какой строке произошло изменение */
function findChange(beforeLists, afterLists, beforeMap, afterMap, keyFn) {
  for (const section of ["parts", "consumables"]) {
    const i = firstDiffIndex(beforeLists[section], afterLists[section]);
    if (i >= 0) {
      const len = (afterLists[section] || []).length;
      if (len === 0) continue;
      return { section, index: Math.min(i, len - 1) };
    }
  }
  // списки совпали — значит изменилось значение по ключу (кол-во, галочка)
  if (beforeMap && afterMap) {
    const keys = new Set(Object.keys(beforeMap).concat(Object.keys(afterMap)));
    for (const k of keys) {
      if (beforeMap[k] === afterMap[k]) continue;
      for (const section of ["parts", "consumables"]) {
        const list = afterLists[section] || [];
        const idx = list.findIndex((it) => keyFn(section, it) === k);
        if (idx >= 0) return { section, index: idx };
      }
    }
  }
  return null;
}

/* Подсвечивает строку и прокручивает к ней */
function highlightAt(bodyPrefix, section, index) {
  const tbody = document.getElementById(bodyPrefix + section);
  if (!tbody) return;
  const tr = tbody.querySelectorAll("tr")[index];
  if (tr) highlightRows([tr]);
}

function restoreSnapshot(json) {
  const state = JSON.parse(json);
  const beforeLists = sections, beforeCounts = counts, beforeChecked = checked;
  sections = state.sections;
  counts = state.counts;
  checked = state.checked || {};
  persistCurrent();
  renderAll();
  const hit = findChange(beforeLists, sections, beforeCounts, counts, countKey)
           || findChange(beforeLists, sections, beforeChecked, checked, countKey);
  if (hit) highlightAt("body-", hit.section, hit.index);
}
const caHistory = makeUndoRedo({
  snapshotFn: snapshot,
  restoreFn: restoreSnapshot,
  undoBtnId: "undoBtn",
  redoBtnId: "redoBtn",
  limit: HISTORY_LIMIT
});
function pushHistory() { caHistory.push(); }

/* ==================== Ключ позиции ====================
   Если у позиции есть код склада — ключ общий по коду (для сквозного расчёта
   и для связи учёта со складом). Если кода нет — ключ локальный (раздел+название). */
function countKey(section, item) {
  return item.code ? ("code::" + item.code) : (section + "::" + item.name);
}

/* ==================== Выделение строк кликом/тапом (мульти-выбор) ==================== */
const selectedCA = { parts: new Set(), consumables: new Set() };
const selectedWH = { parts: new Set(), consumables: new Set() };

function toggleRowPick(store, section, key, tr) {
  if (store[section].has(key)) {
    store[section].delete(key);
    tr.classList.remove("row-picked");
  } else {
    store[section].add(key);
    tr.classList.add("row-picked");
  }
}
function applyPickHighlight(store, section, tbody, list, keyFn) {
  Array.from(tbody.querySelectorAll("tr")).forEach((tr, i) => {
    const item = list[i];
    if (!item) return;
    tr.classList.toggle("row-picked", store[section].has(keyFn(item)));
  });
}

/* ==================== Временная жёлтая подсветка (новая/дублирующая позиция) ====================
   Держится до первого клика в любом месте страницы. */
function flashRow(tr) {
  if (!tr) return;
  setTimeout(() => tr.classList.add("row-flash"), 0);
}

/* ==================== Рендер: вкладка «Учёт» ==================== */
function renderSection(section) {
  const tbody = document.getElementById("body-" + section);
  tbody.innerHTML = "";
  const list = sections[section];
  list.forEach((item, i) => {
    const key = countKey(section, item);
    if (counts[key] === undefined) counts[key] = 0;
    const isChecked = !!checked[key];
    const guest = isGuestMode();
    const tr = document.createElement("tr");
    tr.dataset.key = key;
    tr.innerHTML = `
      <td class="num">${i + 1}</td>
      <td class="code">${item.code ? `<span class="code-text" data-code="${escapeHtml(item.code)}">${formatCodeDisplay(item.code)}</span>` : "—"}</td>
      <td class="name">
        ${escapeHtml(item.name)}
        ${guest ? "" : `<button class="ca-del-badge" data-section="${section}" data-index="${i}" title="Удалить строку">🗑</button>`}
      </td>
      <td class="check">
        <button class="chk-toggle${isChecked ? " on" : ""}" data-section="${section}" data-index="${i}" title="Отметить как учтено">${isChecked ? "✓" : ""}</button>
      </td>
      <td class="count count-merged">
        <div class="count-tier count-tier-num">
          <input type="number" min="0" value="${counts[key]}" class="countInput"
            data-section="${section}" data-index="${i}"${guest ? " readonly tabindex=\"-1\"" : ""}>
        </div>
        ${guest ? "" : `
        <div class="count-tier count-tier-plus">
          <button class="btn plus" data-section="${section}" data-index="${i}" title="Тап: +1. Зажать: указать количество">+</button>
        </div>
        <div class="count-tier count-tier-minus">
          <button class="btn minus" data-section="${section}" data-index="${i}" title="Тап: −1. Зажать: указать количество">–</button>
        </div>`}
      </td>
    `;
    tbody.appendChild(tr);
  });
  applyPickHighlight(selectedCA, section, tbody, list, (it) => countKey(section, it));
  if (typeof applyCaSearch === "function") applyCaSearch();
}
function renderAll() {
  renderSection("parts");
  renderSection("consumables");
  document.getElementById("dateDisplayText").textContent = formatShort(currentDate);
}

function itemAt(section, index) { return sections[section][index]; }

function handleCountClick(e) {
  const section = e.currentTarget.id.replace("body-", "");
  const btn = e.target.closest("button");
  if (btn) {
    const index = parseInt(btn.dataset.index, 10);
    const item = itemAt(section, index);
    if (!item) return;
    const key = countKey(section, item);
    // «plus»/«minus» теперь обрабатываются через pointerdown/pointerup
    // (см. setupQtyLongPress) — короткий тап и долгое нажатие делают разное.
    if (btn.classList.contains("chk-toggle")) {
      checked[key] = !checked[key];
      persistCurrent();
      renderSection(section);
    } else if (btn.classList.contains("ca-del-badge")) {
      if (!confirm(`Удалить «${item.name}» из списка?`)) return;
      pushHistory();
      sections[section].splice(index, 1);
      delete counts[key];
      delete checked[key];
      selectedCA[section].delete(key);
      persistCurrent();
      renderSection(section);
    }
    return;
  }
  const nameTd = e.target.closest("td.name");
  if (nameTd) {
    const tr = nameTd.closest("tr");
    toggleRowPick(selectedCA, section, tr.dataset.key, tr);
  }
}
document.getElementById("body-parts").addEventListener("click", handleCountClick);
document.getElementById("body-consumables").addEventListener("click", handleCountClick);

/* ==================== Учёт: короткое / долгое нажатие на «+»/«–» ====================
   Короткий тап — просто +1 к количеству (или −1; если результат ≤ 0, позиция
   удаляется из списка — та же логика, что раньше была только в модалке).
   Долгое нажатие (зажать ~0.5 c) — открывает модалку с вводом произвольного
   количества (applyQtyAdjust), как было раньше на обычный тап. */
const LONG_PRESS_MS = 500;
const LONG_PRESS_MOVE_TOLERANCE = 12;

function applyQuickAdjust(section, index, mode) {
  const item = itemAt(section, index);
  if (!item) return;
  const key = countKey(section, item);
  pushHistory();
  if (mode === "plus") {
    counts[key] = (counts[key] || 0) + 1;
  } else {
    const newVal = (counts[key] || 0) - 1;
    if (newVal <= 0) {
      sections[section].splice(index, 1);
      delete counts[key];
      delete checked[key];
      selectedCA[section].delete(key);
    } else {
      counts[key] = newVal;
    }
  }
  persistCurrent();
  renderSection(section);
}

function setupQtyLongPress(tbody) {
  let timer = null;
  let longFired = false;
  let activeBtn = null;
  let startX = 0, startY = 0;

  function clearTimer() {
    if (timer) { clearTimeout(timer); timer = null; }
  }
  function reset() {
    clearTimer();
    longFired = false;
    activeBtn = null;
  }
  tbody.addEventListener("pointerdown", (e) => {
    const btn = e.target.closest(".btn.plus, .btn.minus");
    if (!btn) return;
    if (e.pointerType === "mouse" && e.button !== 0) return;
    activeBtn = btn;
    longFired = false;
    startX = e.clientX; startY = e.clientY;
    clearTimer();
    const section = btn.dataset.section;
    const index = Number(btn.dataset.index);
    const mode = btn.classList.contains("plus") ? "plus" : "minus";
    timer = setTimeout(() => {
      longFired = true;
      timer = null;
      if (navigator.vibrate) navigator.vibrate(15);
      openQtyAdjust(section, index, mode);
    }, LONG_PRESS_MS);
  });
  tbody.addEventListener("pointermove", (e) => {
    if (!timer || !activeBtn) return;
    if (Math.abs(e.clientX - startX) > LONG_PRESS_MOVE_TOLERANCE || Math.abs(e.clientY - startY) > LONG_PRESS_MOVE_TOLERANCE) {
      reset();
    }
  });
  tbody.addEventListener("pointerup", (e) => {
    const btn = activeBtn;
    const hadTimer = !!timer;
    clearTimer();
    if (btn && hadTimer && !longFired) {
      const section = btn.dataset.section;
      const index = Number(btn.dataset.index);
      const mode = btn.classList.contains("plus") ? "plus" : "minus";
      applyQuickAdjust(section, index, mode);
    }
    reset();
  });
  tbody.addEventListener("pointercancel", reset);
  tbody.addEventListener("contextmenu", (e) => {
    if (e.target.closest(".btn.plus, .btn.minus")) e.preventDefault();
  });
}
setupQtyLongPress(document.getElementById("body-parts"));
setupQtyLongPress(document.getElementById("body-consumables"));

function handleCountEdit(e) {
  const input = e.target.closest(".countInput");
  if (!input) return;
  const section = input.dataset.section;
  const index = parseInt(input.dataset.index, 10);
  const item = itemAt(section, index);
  if (!item) return;
  const key = countKey(section, item);
  const raw = input.value.trim();
  let val = parseInt(raw, 10);
  if (raw === "" || isNaN(val) || val <= 0) {
    // Стёрли количество (или поставили 0) — позиция целиком удаляется
    // из списка, как и при списании кнопкой «–» до нуля.
    pushHistory();
    sections[section].splice(index, 1);
    delete counts[key];
    delete checked[key];
    selectedCA[section].delete(key);
    persistCurrent();
    renderSection(section);
    return;
  }
  pushHistory();
  counts[key] = val;
  persistCurrent();
  renderSection(section);
}
document.getElementById("body-parts").addEventListener("change", handleCountEdit);
document.getElementById("body-consumables").addEventListener("change", handleCountEdit);
["body-parts","body-consumables"].forEach((id) => {
  document.getElementById(id).addEventListener("keydown", (e) => {
    if (e.key === "Enter" && e.target.classList.contains("countInput")) e.target.blur();
  });
});

/* ==================== Учёт: списать / добавить количество через модалку ====================
   Кнопки «–» и «+» больше не меняют количество напрямую на 1 — открывают
   модалку, где вводится сколько именно списать/добавить. Если после
   списания количество становится 0 или уходит в минус — позиция целиком
   удаляется из списка (отдельной кнопки удаления больше нет). */
let pendingQtyAdjust = null; // { section, index, mode: 'plus'|'minus' }
const qtyAdjustInput = document.getElementById("qtyAdjustInput");

function openQtyAdjust(section, index, mode) {
  const item = itemAt(section, index);
  if (!item) return;
  const key = countKey(section, item);
  const current = counts[key] || 0;
  pendingQtyAdjust = { section, index, mode };
  document.getElementById("qtyAdjustTitle").textContent = (mode === "plus" ? "Добавить: " : "Списать: ") + item.name;
  document.getElementById("qtyAdjustInfo").textContent = "Сейчас в учёте: " + current + " шт."
    + (mode === "minus" ? " Если списать всё (или больше) — позиция будет удалена из списка." : "");
  document.getElementById("qtyAdjustConfirm").textContent = mode === "plus" ? "Добавить" : "Списать";
  document.getElementById("qtyAdjustConfirm").style.background = mode === "plus" ? "var(--accent)" : "var(--danger)";
  qtyAdjustInput.value = "";
  document.getElementById("qtyAdjustOverlay").classList.add("open");
  setTimeout(() => qtyAdjustInput.focus(), 50);
}
function closeQtyAdjust() {
  pendingQtyAdjust = null;
  document.getElementById("qtyAdjustOverlay").classList.remove("open");
}
document.getElementById("qtyAdjustCancel").addEventListener("click", closeQtyAdjust);
document.getElementById("qtyAdjustOverlay").addEventListener("click", (e) => {
  if (e.target.id === "qtyAdjustOverlay") closeQtyAdjust();
});
function applyQtyAdjust() {
  if (!pendingQtyAdjust) return;
  const { section, index, mode } = pendingQtyAdjust;
  const item = itemAt(section, index);
  if (!item) { closeQtyAdjust(); return; }
  const key = countKey(section, item);
  const val = parseInt(qtyAdjustInput.value, 10);
  if (isNaN(val) || val <= 0) { qtyAdjustInput.focus(); return; }
  pushHistory();
  if (mode === "plus") {
    counts[key] = (counts[key] || 0) + val;
  } else {
    const newVal = (counts[key] || 0) - val;
    if (newVal <= 0) {
      sections[section].splice(index, 1);
      delete counts[key];
      delete checked[key];
      selectedCA[section].delete(key);
    } else {
      counts[key] = newVal;
    }
  }
  persistCurrent();
  renderSection(section);
  closeQtyAdjust();
}
document.getElementById("qtyAdjustConfirm").addEventListener("click", applyQtyAdjust);
qtyAdjustInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") applyQtyAdjust();
});

/* ==================== Подтверждение удаления (общее для Склада; в «Учёте» удаление
   теперь происходит автоматически при списании количества до 0, см. applyQtyAdjust) ==================== */
let pendingDelete = null; // { kind: 'reset'|'warehouse'|'whReset'|'onec'|'deleteAll', section, index }

/* ==================== Подтверждение удаления/обнуления (общее для 3 вкладок) ====================
   Раньше у каждого вида удаления (склад, 1С, обнулить учёт, обнулить склад,
   удалить всё) была своя копия «записать pendingDelete → показать текст →
   открыть модалку», а обработчик «Да» разруливал их через 5 почти
   одинаковых if. Теперь одна функция открытия + один конфиг действий. */
function openConfirmDelete(kind, text, section, index) {
  pendingDelete = { kind, section, index };
  document.getElementById("confirmText").textContent = text;
  document.getElementById("confirmOverlay").classList.add("open");
}
function openConfirmWarehouse(section, index) {
  const item = warehouse[section][index];
  openConfirmDelete("warehouse",
    `Удалить «${item.name}» (${item.code}) со склада? Прошлые записи в учёте сохранятся, но перестанут быть связаны со складом.`,
    section, index);
}
function closeConfirm() {
  pendingDelete = null;
  document.getElementById("confirmOverlay").classList.remove("open");
}
document.getElementById("confirmNo").addEventListener("click", closeConfirm);
document.getElementById("confirmOverlay").addEventListener("click", (e) => {
  if (e.target.id === "confirmOverlay") closeConfirm();
});

// Что делает каждый вид подтверждения. pendingDelete доступен внутри
// (section/index — если действие точечное, для «обнулить»/«удалить всё» не нужны).
const DELETE_ACTIONS = {
  whReset: () => {
    pushWhHistory();
    ["parts", "consumables"].forEach((sec) => {
      warehouse[sec].forEach((it) => { it.qty = 0; });
    });
    saveWarehouse();
    renderWarehouseAll();
  },
  warehouse: () => {
    pushWhHistory();
    const { section, index } = pendingDelete;
    const item = warehouse[section][index];
    const key = countKey(section, item);
    warehouse[section].splice(index, 1);
    selectedWH[section].delete(key);
    saveWarehouse();
    renderWarehouseAll();
  },
  onec: () => {
    pushOcHistory();
    const { section, index } = pendingDelete;
    onec[section].splice(index, 1);
    saveOneC();
    renderOneCAll();
  },
  deleteAll: () => {
    pushHistory();
    sections.parts = [];
    sections.consumables = [];
    counts = {};
    checked = {};
    selectedCA.parts.clear();
    selectedCA.consumables.clear();
    persistCurrent();
    renderAll();
  },
};
document.getElementById("confirmYes").addEventListener("click", () => {
  if (!pendingDelete) return;
  const action = DELETE_ACTIONS[pendingDelete.kind];
  if (action) action();
  closeConfirm();
});

document.getElementById("deleteAllBtn").addEventListener("click", () => {
  openConfirmDelete("deleteAll",
    `Удалить ВСЕ позиции (детали и расходники) за ${formatFull(currentDate)}? Счётчики и сами строки будут стёрты полностью. Это можно отменить кнопкой ↶.`);
});

/* ==================== Поиск по складу/1С (автоподбор для панелей добавления/редактирования) ====================
   Раньше searchWarehouse/searchOneC и renderSuggestions/renderOneCSuggestions
   были парами почти одинаковых функций — отличались только тем, в каком
   хранилище искать и что написать, если совпадений нет. Теперь один общий
   поиск и один общий рендер подсказок с этими двумя как параметрами. */
function searchStore(store, query) {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  const results = [];
  ["parts", "consumables"].forEach((section) => {
    store[section].forEach((item) => {
      const name = (item.name || "").toLowerCase();
      const code = (item.code || "").toLowerCase();
      if (name.includes(q) || code.includes(q)) {
        results.push({ section, code: item.code || "", name: item.name });
      }
    });
  });
  return results.slice(0, 8);
}
function renderSuggestionsFrom(box, query, onPick, store, emptyText) {
  const results = searchStore(store, query);
  if (!query.trim()) { box.classList.remove("open"); box.innerHTML = ""; return; }
  if (results.length === 0) {
    box.innerHTML = `<div class="suggest-empty">${emptyText}</div>`;
    box.classList.add("open");
    return;
  }
  box.innerHTML = results.map((r, idx) =>
    `<div class="suggest-item" data-idx="${idx}">
       <span class="code">${escapeHtml(r.code || "—")}</span> — ${escapeHtml(r.name)}
     </div>`
  ).join("");
  box.classList.add("open");
  Array.from(box.querySelectorAll(".suggest-item")).forEach((el) => {
    el.addEventListener("click", () => {
      onPick(results[parseInt(el.dataset.idx, 10)]);
      box.classList.remove("open");
      box.innerHTML = "";
    });
  });
}
function renderSuggestions(box, query, onPick) {
  renderSuggestionsFrom(box, query, onPick, warehouse,
    "Совпадений на складе нет — можно добавить как новую позицию без кода.");
}

/* --- Добавление новой позиции в дневной список --- */
let addPicked = null; // { code, name } если выбрано из подсказки
const newItemInput = document.getElementById("newItemName");
const addSuggestBox = document.getElementById("addSuggestBox");
// На iOS при открытии клавиатуры видимая область экрана уменьшается уже
// ПОСЛЕ того, как страница отрисовалась — из-за этого поле может оказаться
// под прилипающей шапкой. Подстраховываемся: после открытия клавиатуры
// прокручиваем поле в центр видимой области.
newItemInput.addEventListener("focus", () => {
  setTimeout(() => {
    newItemInput.scrollIntoView({ block: "center", behavior: "smooth" });
  }, 300);
});
newItemInput.addEventListener("input", () => {
  addPicked = null;
  renderSuggestions(addSuggestBox, newItemInput.value, (r) => {
    addPicked = r;
    newItemInput.value = r.name;
    document.getElementById("newItemSection").value = r.section;
  });
});

registerSuggestZone(addSuggestBox, [newItemInput]);

document.getElementById("addItemBtn").addEventListener("click", () => {
  const section = document.getElementById("newItemSection").value;
  const name = newItemInput.value.trim();
  if (!name) return;
  const code = (addPicked && addPicked.name === name) ? addPicked.code : "";
  const dupIndex = sections[section].findIndex((it) => it.name === name);
  if (dupIndex !== -1) {
    alert("Такая позиция уже есть в этом списке.");
    const tbody = document.getElementById("body-" + section);
    flashRow(tbody.querySelectorAll("tr")[dupIndex]);
    return;
  }
  const qtyInput = document.getElementById("newItemQty");
  let qty = parseInt(qtyInput.value, 10);
  if (isNaN(qty) || qty < 1) qty = 1;   // не указали — считаем как 1
  pushHistory();
  const newItem = { name, code };
  sections[section].push(newItem);
  counts[countKey(section, newItem)] = qty;
  persistCurrent();
  newItemInput.value = "";
  qtyInput.value = "";
  addPicked = null;
  addSuggestBox.classList.remove("open");
  renderSection(section);
  const tbody = document.getElementById("body-" + section);
  const rows = tbody.querySelectorAll("tr");
  flashRow(rows[rows.length - 1]);
});
newItemInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") document.getElementById("addItemBtn").click();
});
document.getElementById("newItemQty").addEventListener("keydown", (e) => {
  if (e.key === "Enter") document.getElementById("addItemBtn").click();
});

/* --- Редактирование позиции дневного списка (с поиском по складу) --- */
let editingTarget = null; // { section, index }
let editPicked = null;
const editItemInput = document.getElementById("editItemInput");
const editSuggestBox = document.getElementById("editSuggestBox");
registerSuggestZone(editSuggestBox, [editItemInput]);

function openEditItem(section, index) {
  editingTarget = { section, index };
  editPicked = null;
  const item = itemAt(section, index);
  editItemInput.value = item.name;
  document.getElementById("editItemSection").value = section;
  editSuggestBox.classList.remove("open");
  document.getElementById("editItemOverlay").classList.add("open");
  setTimeout(() => { editItemInput.focus(); editItemInput.select(); }, 50);
}
function closeEditItem() {
  editingTarget = null;
  document.getElementById("editItemOverlay").classList.remove("open");
}
editItemInput.addEventListener("input", () => {
  editPicked = null;
  renderSuggestions(editSuggestBox, editItemInput.value, (r) => {
    editPicked = r;
    editItemInput.value = r.name;
  });
});
document.getElementById("editItemCancel").addEventListener("click", closeEditItem);
document.getElementById("editItemOverlay").addEventListener("click", (e) => {
  if (e.target.id === "editItemOverlay") closeEditItem();
});
document.getElementById("editItemSave").addEventListener("click", () => {
  if (!editingTarget) return;
  const { section, index } = editingTarget;
  const newSection = document.getElementById("editItemSection").value;
  const oldItem = itemAt(section, index);
  const trimmed = editItemInput.value.trim();
  if (!trimmed) { closeEditItem(); return; }
  const code = (editPicked && editPicked.name === trimmed) ? editPicked.code : "";
  const sectionChanged = newSection !== section;
  if (!sectionChanged && trimmed === oldItem.name && code === oldItem.code) { closeEditItem(); return; }

  // проверка дублей в разделе назначения
  const clash = sections[newSection].some((it, i) => {
    if (!sectionChanged && i === index) return false;
    return it.name === trimmed;
  });
  if (clash) {
    alert(sectionChanged
      ? `Позиция «${trimmed}» уже есть в разделе «${newSection === "parts" ? "Детали" : "Расходники"}».`
      : "Позиция с таким названием уже есть в этом списке.");
    return;
  }

  pushHistory();
  const oldKey = countKey(section, oldItem);
  const newItem = { name: trimmed, code };
  const newKey = countKey(newSection, newItem);
  const savedCount = counts[oldKey] || 0;
  const savedChecked = checked[oldKey] || false;
  const wasPicked = selectedCA[section].has(oldKey);

  if (sectionChanged) {
    sections[section].splice(index, 1);
    sections[newSection].push(newItem);
  } else {
    sections[section][index] = newItem;
  }

  if (newKey !== oldKey) {
    counts[newKey] = savedCount;
    checked[newKey] = savedChecked;
    delete counts[oldKey];
    delete checked[oldKey];
  }
  selectedCA[section].delete(oldKey);
  if (wasPicked) selectedCA[newSection].add(newKey);

  persistCurrent();
  if (sectionChanged) {
    renderAll();
    // подсветим, куда переехала позиция
    const tbody = document.getElementById("body-" + newSection);
    const rows = tbody.querySelectorAll("tr");
    flashRow(rows[rows.length - 1]);
  } else {
    renderSection(section);
  }
  closeEditItem();
});
editItemInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") document.getElementById("editItemSave").click();
});

/* ==================== История выдачи по позиции (только расход по дням) ==================== */
let historyTarget = null; // { key, name }

function collectHistoryEntries(key) {
  const map = {}; // date -> minus (кол-во выдано в этот день)
  Object.keys(dataByDate).forEach((date) => {
    const c = (dataByDate[date] && dataByDate[date].counts) || {};
    if (c[key]) map[date] = (map[date] || 0) + c[key];
  });
  return map;
}

function renderHistoryList() {
  if (!historyTarget) return;
  const from = document.getElementById("historyFrom").value;
  const to = document.getElementById("historyTo").value;
  const map = collectHistoryEntries(historyTarget.key);
  let dates = Object.keys(map).filter((d) => (!from || d >= from) && (!to || d <= to));
  dates.sort().reverse();
  const list = document.getElementById("historyList");
  if (dates.length === 0) {
    list.innerHTML = `<div class="history-empty">Нет данных о выдаче за выбранный период.</div>`;
    return;
  }
  list.innerHTML = dates.map((d) =>
    `<div class="history-row"><span class="h-date">${formatShort(d)}</span><span class="h-minus">−${map[d]} шт</span></div>`
  ).join("");
}

function openHistory(section, item) {
  const key = countKey(section, item);
  historyTarget = { key, name: item.name };
  document.getElementById("historyTitle").textContent = "История выдачи: " + item.name;
  document.getElementById("historyFrom").value = "";
  document.getElementById("historyTo").value = "";
  renderHistoryList();
  document.getElementById("historyOverlay").classList.add("open");
}
function closeHistory() {
  historyTarget = null;
  document.getElementById("historyOverlay").classList.remove("open");
}
document.getElementById("historyFrom").addEventListener("change", renderHistoryList);
document.getElementById("historyTo").addEventListener("change", renderHistoryList);
document.getElementById("historyClose").addEventListener("click", closeHistory);
document.getElementById("historyOverlay").addEventListener("click", (e) => {
  if (e.target.id === "historyOverlay") closeHistory();
});

/* ==================== Печать этикеток для коробок (Склад) ====================
   Лист A4, этикетки 7x5 см, зазор 2 мм, 2x4=8 на лист (с запасом под
   системную печать — Safari добавляет свою шапку/подвал).
   ВАЖНО: используем тот же #printArea + window.print(), что и обычный
   экспорт — открытие через window.open() в установленном на «Домой»
   PWA виснет без адресной строки и кнопки закрытия. */
function buildWarehouseLabelHtml(name, code) {
  return `<div class="print-label"><div class="print-label-name">${escapeHtml(name)}</div>${code ? `<div class="print-label-code">${escapeHtml(code)}</div>` : ""}</div>`;
}
function printWarehouseLabels(item) {
  const labelHtml = buildWarehouseLabelHtml(item.name, item.code || "");
  const printArea = document.getElementById("printArea");
  printArea.innerHTML = `<div class="print-labels-grid" style="grid-template-columns: repeat(2, 70mm);">${labelHtml.repeat(8)}</div>`;
  window.print();
}

/* ==================== Печать этикетки: ручной ввод ====================
   Отдельный, более крупный формат — 8x3.5 см, 2x5=10 на лист, лист всегда
   заполняется целиком одинаковыми копиями (без отдельного поля «копий»).
   «Шт» — не количество копий, а число, печатаемое В УГЛУ каждой этикетки
   (например «60 шт») — по желанию, необязательное поле. */
function buildManualLabelHtml(name, code, qty) {
  const qtyNum = parseInt(qty, 10);
  const showQty = qty && !isNaN(qtyNum) && qtyNum > 0; // "0" или пусто — не печатаем
  return `<div class="print-label manual">
    <div class="print-label-name">${escapeHtml(name)}</div>
    ${code ? `<div class="print-label-code">${escapeHtml(code)}</div>` : ""}
    ${showQty ? `<div class="print-label-qty">${qtyNum} шт</div>` : ""}
  </div>`;
}
const MANUAL_LABELS_PER_PAGE = 10; // 2x5
// entries — массив { name, code, qty, copies } собирается из всех строк
// мини-таблицы при печати; каждая позиция даёт `copies` одинаковых
// этикеток, все копии всех позиций складываются в общий список и режутся
// по MANUAL_LABELS_PER_PAGE на отдельные страницы.
function printManualLabels(entries) {
  const allLabels = [];
  entries.forEach((e) => {
    const html = buildManualLabelHtml(e.name, e.code, e.qty);
    const copies = Math.max(1, e.copies || 1);
    for (let i = 0; i < copies; i++) allLabels.push(html);
  });
  const pages = [];
  for (let i = 0; i < allLabels.length; i += MANUAL_LABELS_PER_PAGE) {
    const slice = allLabels.slice(i, i + MANUAL_LABELS_PER_PAGE).join("");
    pages.push(`<div class="print-labels-page"><div class="print-labels-grid" style="grid-template-columns: repeat(2, 80mm);">${slice}</div></div>`);
  }
  document.getElementById("printArea").innerHTML = pages.join("");
  window.print();
}

/* --- Модалка ручного ввода этикеток (кнопка «⋮» → «🖨️ Печать») ====================
   Мини-таблица: каждая строка — своя позиция (Название+Шт / Код+Кол-во
   копий), с автоподбором по складу (как в панели добавления «Учёта») и
   крестиком удаления. «+» снизу добавляет ещё строку. */
let printLabelRowSeq = 0;
function createPrintLabelRow() {
  const id = "plr" + (++printLabelRowSeq);
  const row = document.createElement("div");
  row.className = "print-label-row";
  row.dataset.rowId = id;
  row.innerHTML = `
    <button class="plr-del" title="Удалить эту позицию">✕</button>
    <div class="plr-line">
      <div class="plr-name-wrap">
        <input type="text" class="plr-name" placeholder="Название *" autocomplete="off">
        <div class="suggest-box plr-suggest"></div>
      </div>
      <div class="plr-side">
        <input type="number" class="plr-qty" min="0" placeholder="Шт">
      </div>
    </div>
    <div class="plr-line" style="margin-top:6px;">
      <div class="plr-name-wrap">
        <input type="text" class="plr-code" placeholder="Код (необязательно)" autocomplete="off">
      </div>
      <div class="plr-side">
        <input type="number" class="plr-copies" min="1" placeholder="Копий">
      </div>
    </div>
  `;
  const nameInput = row.querySelector(".plr-name");
  const codeInput = row.querySelector(".plr-code");
  const suggestBox = row.querySelector(".plr-suggest");
  // Подсказки выносим в <body> и позиционируем через position:fixed —
  // иначе их обрезает скролл-контейнер строк (#printLabelRows), даже с
  // высоким z-index (overflow родителя обрезает потомков всегда).
  suggestBox.classList.add("plr-suggest-fixed");
  document.body.appendChild(suggestBox);
  function positionSuggestBox() {
    const r = nameInput.getBoundingClientRect();
    suggestBox.style.left = r.left + "px";
    suggestBox.style.width = r.width + "px";
    suggestBox.style.top = (r.bottom + 4) + "px";
  }
  let picked = null;
  function handleInput() {
    picked = null;
    positionSuggestBox();
    renderSuggestions(suggestBox, nameInput.value || codeInput.value, (r) => {
      picked = r;
      nameInput.value = r.name;
      codeInput.value = r.code || "";
      suggestBox.classList.remove("open");
    });
  }
  nameInput.addEventListener("input", handleInput);
  codeInput.addEventListener("input", handleInput);
  // При открытии клавиатуры экран пересчитывается не мгновенно — если
  // позиционировать сразу на focus, подсказка «залипает» на месте, где
  // поле было ДО появления клавиатуры (баг именно у первого поля в
  // модалке — у остальных клавиатура уже открыта, и это не заметно).
  // Пересчитываем с небольшой задержкой, пока анимация ещё идёт, и на
  // всех последующих кадрах через requestAnimationFrame — так подсказка
  // «догоняет» реальное положение поля независимо от строки.
  function positionSuggestBoxSettled() {
    positionSuggestBox();
    requestAnimationFrame(positionSuggestBox);
    setTimeout(positionSuggestBox, 150);
    setTimeout(positionSuggestBox, 350);
  }
  nameInput.addEventListener("focus", positionSuggestBoxSettled);
  codeInput.addEventListener("focus", positionSuggestBoxSettled);
  window.addEventListener("resize", () => {
    if (suggestBox.classList.contains("open")) positionSuggestBox();
  });
  document.getElementById("printLabelRows").addEventListener("scroll", () => {
    if (suggestBox.classList.contains("open")) positionSuggestBox();
  }, { passive: true });
  registerSuggestZone(suggestBox, [nameInput, codeInput]);
  row.querySelector(".plr-del").addEventListener("click", () => {
    const rows = document.querySelectorAll(".print-label-row");
    if (rows.length <= 1) {
      // последнюю строку не удаляем совсем — просто очищаем поля
      if (!confirm("Очистить эту позицию?")) return;
      nameInput.value = ""; codeInput.value = "";
      row.querySelector(".plr-qty").value = "";
      row.querySelector(".plr-copies").value = "";
      return;
    }
    if (!confirm("Удалить эту позицию?")) return;
    suggestBox.remove();
    row.remove();
  });
  return row;
}
function removeDetachedPrintSuggestBoxes() {
  document.querySelectorAll(".plr-suggest-fixed").forEach((el) => el.remove());
}
function openPrintLabelModal() {
  removeDetachedPrintSuggestBoxes();
  const container = document.getElementById("printLabelRows");
  container.innerHTML = "";
  container.appendChild(createPrintLabelRow());
  document.getElementById("printLabelOverlay").classList.add("open");
}
function closePrintLabelModal() {
  removeDetachedPrintSuggestBoxes();
  document.getElementById("printLabelOverlay").classList.remove("open");
}
document.getElementById("printLabelBtn").addEventListener("click", openPrintLabelModal);
document.getElementById("printLabelCancel").addEventListener("click", closePrintLabelModal);
document.getElementById("printLabelOverlay").addEventListener("click", (e) => {
  if (e.target.id !== "printLabelOverlay") return;
  // Защита от случайного тапа мимо формы — спрашиваем подтверждение,
  // а не закрываем сразу (иначе введённые позиции терялись без вопросов).
  if (!confirm("Закрыть окно печати? Введённые позиции не сохранятся.")) return;
  closePrintLabelModal();
});
document.getElementById("printLabelAddRow").addEventListener("click", () => {
  document.getElementById("printLabelRows").appendChild(createPrintLabelRow());
});
document.getElementById("printLabelGo").addEventListener("click", () => {
  const rows = Array.from(document.querySelectorAll(".print-label-row"));
  const entries = [];
  let firstEmptyNameInput = null;
  rows.forEach((row) => {
    const name = row.querySelector(".plr-name").value.trim();
    const code = row.querySelector(".plr-code").value.trim();
    const qty = row.querySelector(".plr-qty").value.trim();
    const copiesRaw = row.querySelector(".plr-copies").value.trim();
    const copies = copiesRaw ? Math.max(1, parseInt(copiesRaw, 10) || 1) : 1;
    if (!name) {
      if (!firstEmptyNameInput) firstEmptyNameInput = row.querySelector(".plr-name");
      return; // пустые строки (без названия) просто пропускаем
    }
    entries.push({ name, code, qty, copies });
  });
  if (entries.length === 0) {
    alert("Заполните название хотя бы для одной позиции.");
    if (firstEmptyNameInput) firstEmptyNameInput.focus();
    return;
  }
  closePrintLabelModal();
  printManualLabels(entries);
});

