/* ==================== Ноль в числовых полях ====================
   При установке курсора в поле со значением 0 оно очищается,
   чтобы ввод не превращался в «0129». Если ушли, ничего не введя,
   ноль возвращается. Программная правка value не вызывает change,
   поэтому лишних сохранений не происходит. */
function isNumberField(el) {
  return el && el.tagName === "INPUT" && el.type === "number";
}
document.addEventListener("focusin", (e) => {
  const el = e.target;
  if (isNumberField(el) && el.value === "0") el.value = "";
});
document.addEventListener("focusout", (e) => {
  const el = e.target;
  if (isNumberField(el) && el.value.trim() === "") el.value = "0";
});


/* ==================== Перенос позиции 1C на склад ====================
   Кнопка «+» есть только у позиций без связи со складом. Код берётся из 1C —
   именно по нему связь и возникает; название на складе можно задать своё. */
let ocToWhTarget = null;

function openOcToWh(section, index) {
  const item = onec[section][index];
  if (!item) return;
  if (warehouseInfoFor(item.code)) {          // связь уже есть — нечего добавлять
    alert("Эта позиция уже есть на складе.");
    return;
  }
  ocToWhTarget = { section, index };
  document.getElementById("ocToWhSection").value = section === "parts" ? "Детали" : "Расходники";
  document.getElementById("ocToWhCode").value = item.code || "";
  document.getElementById("ocToWhName").value = item.name;
  document.getElementById("ocToWhQty").value = 0;
  document.getElementById("ocToWhOverlay").classList.add("open");
  setTimeout(() => {
    const n = document.getElementById("ocToWhName");
    n.focus(); n.select();
  }, 50);
}
function closeOcToWh() {
  ocToWhTarget = null;
  document.getElementById("ocToWhOverlay").classList.remove("open");
}
document.getElementById("ocToWhCancel").addEventListener("click", closeOcToWh);
document.getElementById("ocToWhOverlay").addEventListener("click", (e) => {
  if (e.target.id === "ocToWhOverlay") closeOcToWh();
});
document.getElementById("ocToWhSave").addEventListener("click", () => {
  if (!ocToWhTarget) return;
  const { section, index } = ocToWhTarget;
  const item = onec[section][index];
  if (!item) { closeOcToWh(); return; }
  const name = document.getElementById("ocToWhName").value.trim();
  let qty = parseInt(document.getElementById("ocToWhQty").value, 10);
  if (isNaN(qty) || qty < 0) qty = 0;
  if (!name) { alert("Укажите наименование для склада."); return; }
  const code = item.code || "";
  if (code && warehouseInfoFor(code)) { alert("Позиция с таким кодом уже есть на складе."); closeOcToWh(); return; }

  pushWhHistory();
  warehouse[section].push({ code, name, qty });
  saveWarehouse();
  renderWarehouseAll();
  renderOneCAll();
  closeOcToWh();

  // подсветим строку 1C — у неё появилась зелёная связь со складом
  const tbody = document.getElementById("oc-body-" + section);
  flashRow(tbody.querySelectorAll("tr")[index]);
});
document.getElementById("ocToWhName").addEventListener("keydown", (e) => {
  if (e.key === "Enter") document.getElementById("ocToWhSave").click();
});


/* ==================== Итоги по колонкам ====================
   Под заголовком показывается сумма по разделу. Позиции без связи
   в сумму «чужой» колонки не попадают (там прочерк, а не ноль). */
function fmtTotal(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}
function setTotal(id, value) {
  const el = document.getElementById(id);
  if (el) el.textContent = fmtTotal(value);
}

function updateWarehouseTotals(section) {
  const list = warehouse[section];
  let own = 0, oc = 0;
  list.forEach((it) => {
    own += it.qty || 0;
    const info = oneCInfoFor(it.code);
    if (info) oc += info.qty;
  });
  setTotal(`total-wh-${section}-qty`, own);
  setTotal(`total-wh-${section}-ocqty`, oc);
}

function updateOneCTotals(section) {
  const list = onec[section];
  let own = 0, wh = 0;
  list.forEach((it) => {
    own += it.qty || 0;
    const info = warehouseInfoFor(it.code);
    if (info) wh += info.qty;
  });
  setTotal(`total-oc-${section}-qty`, own);
  setTotal(`total-oc-${section}-whqty`, wh);
}

/* ==================== Синхронизация через GitHub Gist ====================
   Данные (dataByDate, warehouse, onec, currentDate) хранятся дополнительно
   в приватном Gist пользователя. При изменениях — отправляем туда (с
   задержкой, чтобы не слать запрос на каждое нажатие). При открытии —
   подтягиваем актуальную версию, чтобы на любом устройстве было видно
   одно и то же. Правило при конфликте — побеждает последнее сохранение
   (кто последний нажал/подождал синхронизации, тот и главный). */
const SYNC_TOKEN_KEY = "potreblenie_sync_token_v1";
const SYNC_GIST_ID_KEY = "potreblenie_sync_gist_id_v1";
// Роль устройства: "главное" всегда побеждает при конфликте и не спрашивает
// подтверждения; "подчинённое" при конфликте всегда молча берёт версию с
// сервера и вдобавок сам периодически проверяет сервер, пока открыто.
const SYNC_PRIMARY_KEY = "potreblenie_sync_primary_v1";
function isPrimaryDevice() { return localStorage.getItem(SYNC_PRIMARY_KEY) === "1"; }
const SYNC_SETTINGS_PW_KEY = "potreblenie_sync_settings_pw_v1";
function getSyncPassword() { return localStorage.getItem(SYNC_SETTINGS_PW_KEY) || ""; }
function setSyncPassword(pw) { localStorage.setItem(SYNC_SETTINGS_PW_KEY, pw); }
function changeSyncPassword() {
  const current = getSyncPassword();
  if (current) {
    const entered = prompt("Текущий пароль:");
    if (entered === null) return;
    if (entered !== current) { alert("Неверный пароль."); return; }
  }
  const next = prompt(current ? "Новый пароль:" : "Задайте пароль для настроек синхронизации:");
  if (next === null) return;
  if (!next.trim()) { alert("Пароль не может быть пустым."); return; }
  setSyncPassword(next.trim());
  alert("Пароль сохранён.");
}
function verifySyncPassword() {
  const stored = getSyncPassword();
  if (!stored) return true; // пароль ещё не задан — доступ без проверки
  const entered = prompt("Пароль настроек синхронизации:");
  if (entered === null) return false;
  if (entered !== stored) { alert("Неверный пароль."); return false; }
  return true;
}
function openSyncModalGated() {
  if (!verifySyncPassword()) return;
  openSyncModal();
}
function quickSyncAction() {
  if (!isSyncConfigured()) { openSyncModalGated(); return; }
  if (isPrimaryDevice()) pushToGistNow(); else pullFromGist();
}
// Гостевой режим: синхронизация настроена, но это устройство не главное —
// на вкладке «Учёт» скрываем +/- и добавление, оставляем только список с поиском.
function isGuestMode() { return isSyncConfigured() && !isPrimaryDevice(); }
function updateGuestModeUI() {
  const panel = document.getElementById("addPanelConsumption");
  if (panel) panel.style.display = isGuestMode() ? "none" : "";
  renderAll();
}
const SECONDARY_POLL_MS = 30000; // как часто подчинённое устройство само проверяет сервер
let secondaryPollTimer = null;
const SYNC_FILENAME = "sklad-sync-data.json";
// История сохранений — отдельный файл в том же Gist (Gist поддерживает
// несколько файлов). Так она переживает переустановку приложения и очистку
// браузера, и видна на всех устройствах одинаково.
const SYNC_HISTORY_FILENAME = "sklad-sync-history.json";
// Ждём 60 секунд ПОСЛЕ ПОСЛЕДНЕГО действия, прежде чем отправлять данные на
// сервер (debounce, не троттлинг): если действия идут одно за другим быстрее,
// чем раз в минуту, отправка откладывается до паузы. Не зависит от того,
// остаётесь вы в приложении или закрываете его — при уходе (см. flushSyncNow)
// несохранённые правки всё равно отправляются немедленно.
const SYNC_DEBOUNCE_MS = 20000;
// "Отметки времени", по которым мы понимаем, кто последний менял данные —
// это устройство или сервер (см. подробное объяснение в конце файла / в чате).
const LOCAL_UPDATED_AT_KEY = "potreblenie_local_updated_v1";
const SYNC_LAST_SYNCED_AT_KEY = "potreblenie_last_synced_v1";

let syncTimer = null;
let syncInFlight = false;
let syncQueued = false; // изменение пришло, пока предыдущая отправка ещё была в процессе — досылаем её сразу после
let applyingRemote = false;
let pendingConflict = null; // { remotePayload, localPayload } — пока пользователь не выбрал вариант

/* ---- Отслеживание "есть ли несохранённые на сервере изменения" ---- */
function getLocalUpdatedAt() { return Number(localStorage.getItem(LOCAL_UPDATED_AT_KEY) || 0); }
function getLastSyncedAt() { return Number(localStorage.getItem(SYNC_LAST_SYNCED_AT_KEY) || 0); }

// Вызывается при КАЖДОМ локальном изменении данных (см. scheduleSync ниже).
function markLocalChange() {
  try { localStorage.setItem(LOCAL_UPDATED_AT_KEY, String(Date.now())); } catch (e) {}
  updateDirtyIndicator();
}
// Вызывается после того, как мы точно знаем, что локальные данные и данные
// на сервере совпадают (успешный push или успешный pull). Если передан
// dataSnapshot (сами синхронизированные данные), заодно сравниваем их с
// состоянием на момент предыдущей синхронизации и пишем запись в историю.
function markSyncedTo(updatedAt, dataSnapshot, kind) {
  const t = updatedAt || Date.now();
  try {
    localStorage.setItem(SYNC_LAST_SYNCED_AT_KEY, String(t));
    localStorage.setItem(LOCAL_UPDATED_AT_KEY, String(t));
  } catch (e) {}
  if (dataSnapshot) {
    const prev = loadSyncLastState();
    if (!prev) {
      // Не с чем сравнивать (первая синхронизация на этом устройстве) —
      // не считаем диф (иначе туда попадёт вообще весь склад/учёт как
      // "добавлено"), просто фиксируем сам факт.
      addSyncHistoryEntry(kind || "push", ["Первая синхронизация — сохранено текущее состояние"]);
    } else {
      const lines = buildChangeSummary(prev, dataSnapshot);
      if (lines.length > 0) addSyncHistoryEntry(kind || "push", lines);
    }
    saveSyncLastState(dataSnapshot);
  }
  updateDirtyIndicator();
}
// Есть ли на этом устройстве правки, которые ещё не долетели до сервера?
function isDirty() {
  return isSyncConfigured() && getLocalUpdatedAt() > getLastSyncedAt();
}
function updateDirtyIndicator() {
  const btn = document.getElementById("syncBtn");
  if (!btn) return;
  btn.classList.toggle("dirty", isDirty());
}

function getSyncConfig() {
  return {
    token: localStorage.getItem(SYNC_TOKEN_KEY) || "",
    gistId: localStorage.getItem(SYNC_GIST_ID_KEY) || ""
  };
}
function isSyncConfigured() {
  return !!getSyncConfig().token;
}

function setSyncStatus(state, text) {
  const btn = document.getElementById("syncBtn");
  const line = document.getElementById("syncStatusLine");
  btn.classList.remove("err", "syncing");
  const icons = { idle: "⚙", syncing: "⏳", ok: "☁", err: "⚠", off: "⚙" };
  if (state === "syncing") btn.classList.add("syncing");
  if (state === "err") btn.classList.add("err");
  btn.textContent = icons[state] || "⚙";
  if (line) {
    line.textContent = text || "";
    line.classList.toggle("err", state === "err");
  }
}

function buildSyncPayload() {
  return {
    updatedAt: Date.now(),
    dataByDate,
    warehouse,
    onec,
    currentDate
  };
}

/* ==================== История сохранений ====================
   Отдельный локальный журнал (не уходит в Gist): при каждой успешной
   отправке на сервер или загрузке с сервера сравниваем новые данные с
   теми, что были на момент предыдущей синхронизации, и запоминаем время
   + краткое описание того, что изменилось (какие позиции добавлены,
   удалены, у каких изменилось количество). Хранится только на этом
   устройстве и нужна, чтобы можно было понять, что и когда сохранилось. */
const SYNC_LAST_STATE_KEY = "potreblenie_sync_laststate_v1";
const SYNC_HISTORY_KEY = "potreblenie_sync_history_v1";
const SYNC_HISTORY_LIMIT = 40;

function loadSyncLastState() {
  try {
    const raw = localStorage.getItem(SYNC_LAST_STATE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
}
function saveSyncLastState(data) {
  try {
    localStorage.setItem(SYNC_LAST_STATE_KEY, JSON.stringify({
      dataByDate: data.dataByDate, warehouse: data.warehouse, onec: data.onec
    }));
  } catch (e) {}
}
function loadSyncHistory() {
  try {
    const raw = localStorage.getItem(SYNC_HISTORY_KEY);
    const arr = raw ? JSON.parse(raw) : [];
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}
function saveSyncHistoryList() {
  try { localStorage.setItem(SYNC_HISTORY_KEY, JSON.stringify(syncHistory)); } catch (e) {}
}
let syncHistory = loadSyncHistory();

function addSyncHistoryEntry(kind, lines) {
  syncHistory.unshift({ time: Date.now(), kind, lines });
  if (syncHistory.length > SYNC_HISTORY_LIMIT) syncHistory.length = SYNC_HISTORY_LIMIT;
  saveSyncHistoryList();
  renderSyncHistory();
}
// Объединяет историю, полученную с сервера (от другого устройства), с тем,
// что уже есть локально. Записи считаются одинаковыми по паре время+тип —
// этого достаточно, коллизии между разными устройствами практически
// невозможны (миллисекундная точность).
function mergeRemoteHistory(historyFileContent) {
  if (!historyFileContent) return;
  let remoteList;
  try { remoteList = JSON.parse(historyFileContent); } catch (e) { return; }
  if (!Array.isArray(remoteList) || remoteList.length === 0) return;
  const seen = new Set(syncHistory.map((e) => e.time + "|" + e.kind));
  let added = false;
  remoteList.forEach((entry) => {
    const sig = entry.time + "|" + entry.kind;
    if (!seen.has(sig)) { syncHistory.push(entry); seen.add(sig); added = true; }
  });
  if (added) {
    syncHistory.sort((a, b) => b.time - a.time);
    if (syncHistory.length > SYNC_HISTORY_LIMIT) syncHistory.length = SYNC_HISTORY_LIMIT;
    saveSyncHistoryList();
    renderSyncHistory();
  }
}

// Ключ позиции для сравнения "было/стало" — так же, как countKey: по коду,
// если он есть, иначе по названию.
function itemDiffKey(item) {
  return item.code ? ("code::" + item.code) : ("name::" + item.name);
}
function labelItem(item) {
  return item.code ? (item.name + " (" + item.code + ")") : item.name;
}
// Сравнивает два списка позиций (например warehouse.parts до/после) и
// возвращает добавленные / удалённые / те, у кого изменилось количество.
function diffItemList(oldList, newList, qtyOf) {
  const oldMap = new Map((oldList || []).map((it) => [itemDiffKey(it), it]));
  const newMap = new Map((newList || []).map((it) => [itemDiffKey(it), it]));
  const added = [], removed = [], changed = [];
  newMap.forEach((item, key) => { if (!oldMap.has(key)) added.push(item); });
  oldMap.forEach((item, key) => { if (!newMap.has(key)) removed.push(item); });
  if (qtyOf) {
    newMap.forEach((item, key) => {
      const oldItem = oldMap.get(key);
      if (!oldItem) return;
      const a = qtyOf(oldItem), b = qtyOf(item);
      if (a !== b) changed.push({ item, from: a, to: b });
    });
  }
  return { added, removed, changed };
}
// Диф для «Склада» и «1С» — там количество лежит прямо в самой позиции (qty).
function diffStore(oldStore, newStore) {
  const lines = [];
  ["parts", "consumables"].forEach((sec) => {
    const secLabel = sec === "parts" ? "Детали" : "Расходники";
    const oldList = oldStore ? oldStore[sec] : [];
    const newList = newStore ? newStore[sec] : [];
    const { added, removed, changed } = diffItemList(oldList, newList, (it) => it.qty);
    added.forEach((it) => lines.push("+ " + secLabel + ": " + labelItem(it) + " (" + it.qty + ")"));
    removed.forEach((it) => lines.push("− " + secLabel + ": " + labelItem(it)));
    changed.forEach((c) => lines.push("~ " + secLabel + ": " + labelItem(c.item) + "  " + c.from + " → " + c.to));
  });
  return lines;
}
// Диф для одного дня «Учёта» — там количество лежит отдельно, в counts,
// под ключом countKey(section, item).
function diffDateEntry(oldEntry, newEntry) {
  const lines = [];
  const oldCounts = (oldEntry && oldEntry.counts) || {};
  const newCounts = (newEntry && newEntry.counts) || {};
  ["parts", "consumables"].forEach((sec) => {
    const secLabel = sec === "parts" ? "Детали" : "Расходники";
    const oldList = (oldEntry && oldEntry.sections && oldEntry.sections[sec]) || [];
    const newList = (newEntry && newEntry.sections && newEntry.sections[sec]) || [];
    const { added, removed } = diffItemList(oldList, newList, null);
    added.forEach((it) => lines.push("+ " + secLabel + ": " + labelItem(it) + " (" + (newCounts[countKey(sec, it)] || 0) + ")"));
    removed.forEach((it) => lines.push("− " + secLabel + ": " + labelItem(it)));
    const oldMap = new Map(oldList.map((it) => [itemDiffKey(it), it]));
    newList.forEach((it) => {
      const key = itemDiffKey(it);
      const oldItem = oldMap.get(key);
      if (!oldItem) return;
      const a = oldCounts[countKey(sec, oldItem)] || 0;
      const b = newCounts[countKey(sec, it)] || 0;
      if (a !== b) lines.push("~ " + secLabel + ": " + labelItem(it) + "  " + a + " → " + b);
    });
  });
  return lines;
}
// Диф по всем датам «Учёта» — показываем не более 5 дат в одной записи истории.
function diffDataByDate(oldData, newData) {
  const lines = [];
  const oldD = oldData || {};
  const newD = newData || {};
  const dates = Array.from(new Set([...Object.keys(oldD), ...Object.keys(newD)])).sort();
  let shown = 0, skipped = 0;
  dates.forEach((date) => {
    const dLines = diffDateEntry(oldD[date], newD[date]);
    if (dLines.length === 0) return;
    if (shown >= 5) { skipped++; return; }
    lines.push("Учёт за " + formatShort(date) + ":");
    dLines.forEach((l) => lines.push("  " + l));
    shown++;
  });
  if (skipped > 0) lines.push("…и ещё изменения за " + skipped + " дат(у/ы)");
  return lines;
}
function buildChangeSummary(oldSnap, newSnap) {
  const lines = [];
  const caLines = diffDataByDate(oldSnap && oldSnap.dataByDate, newSnap.dataByDate);
  lines.push(...caLines);
  const whLines = diffStore(oldSnap && oldSnap.warehouse, newSnap.warehouse);
  if (whLines.length) { lines.push("Склад:"); whLines.forEach((l) => lines.push("  " + l)); }
  const ocLines = diffStore(oldSnap && oldSnap.onec, newSnap.onec);
  if (ocLines.length) { lines.push("1С:"); ocLines.forEach((l) => lines.push("  " + l)); }
  return lines;
}
function formatHistoryTime(ts) {
  const d = new Date(ts);
  const pad = (n) => String(n).padStart(2, "0");
  return pad(d.getDate()) + "." + pad(d.getMonth() + 1) + " " + pad(d.getHours()) + ":" + pad(d.getMinutes());
}
function renderSyncHistory() {
  const box = document.getElementById("syncHistoryList");
  if (!box) return;
  if (syncHistory.length === 0) {
    box.innerHTML = "<div class=\"sync-history-empty\">Пока нет записей — появятся после первого сохранения.</div>";
    return;
  }
  box.innerHTML = syncHistory.map((entry) => {
    const kindLabel = entry.kind === "pull" ? "⇩ загружено с сервера" : "⇧ сохранено на сервер";
    const body = entry.lines && entry.lines.length
      ? entry.lines.map((l) => escapeHtml(l)).join("\n")
      : "(первая запись — состояние на момент подключения синхронизации)";
    return "<div class=\"sync-history-entry\">"
      + "<div class=\"sync-history-head\"><b>" + formatHistoryTime(entry.time) + "</b><span>" + kindLabel + "</span></div>"
      + "<pre class=\"sync-history-body\">" + body + "</pre>"
      + "</div>";
  }).join("");
}

function applySyncPayload(payload) {
  applyingRemote = true;
  try {
    if (payload.dataByDate && typeof payload.dataByDate === "object") {
      dataByDate = payload.dataByDate;
      try { localStorage.setItem(DATA_BY_DATE_KEY, JSON.stringify(dataByDate)); } catch (e) {}
    }
    if (payload.warehouse && Array.isArray(payload.warehouse.parts) && Array.isArray(payload.warehouse.consumables)) {
      warehouse = payload.warehouse;
      try { localStorage.setItem(WAREHOUSE_KEY, JSON.stringify(warehouse)); } catch (e) {}
    }
    if (payload.onec && Array.isArray(payload.onec.parts) && Array.isArray(payload.onec.consumables)) {
      onec = payload.onec;
      try { localStorage.setItem(ONEC_KEY, JSON.stringify(onec)); } catch (e) {}
    }
    if (payload.currentDate) {
      currentDate = payload.currentDate;
      try { localStorage.setItem(LAST_DATE_KEY, currentDate); } catch (e) {}
    }
    const entry = entryFor(currentDate);
    sections = entry.sections;
    counts = entry.counts;
    checked = entry.checked;
    selectedCA.parts.clear();
    selectedCA.consumables.clear();
    selectedWH.parts.clear();
    selectedWH.consumables.clear();
    selectedOC.parts.clear();
    selectedOC.consumables.clear();
    caHistory.reset();
    whHistory.reset();
    ocHistory.reset();
    rebuildCrossIndexes();
    dateInput.value = currentDate;
    renderAll();
    renderWarehouseAll();
    renderOneCAll();
  } finally {
    applyingRemote = false;
  }
}

async function githubGistRequest(method, url, token, body) {
  const res = await fetch(url, {
    method,
    headers: {
      "Authorization": "token " + token,
      "Accept": "application/vnd.github+json",
      "Content-Type": "application/json"
    },
    body: body ? JSON.stringify(body) : undefined
  });
  if (!res.ok) {
    let msg = "Ошибка " + res.status;
    if (res.status === 401) msg = "Неверный токен";
    if (res.status === 404) msg = "Gist не найден (проверьте ID)";
    throw new Error(msg);
  }
  return res.json();
}

async function pullFromGist(silent) {
  const { token, gistId } = getSyncConfig();
  if (!token || !gistId) return false;
  if (!silent) setSyncStatus("syncing", "Загрузка с сервера…");
  try {
    const data = await githubGistRequest("GET", "https://api.github.com/gists/" + gistId, token);
    mergeRemoteHistory(data.files && data.files[SYNC_HISTORY_FILENAME] && data.files[SYNC_HISTORY_FILENAME].content);
    const file = data.files && data.files[SYNC_FILENAME];
    if (!file || !file.content) {
      setSyncStatus("err", "В Gist пока нет данных приложения");
      return false;
    }
    const payload = JSON.parse(file.content);
    applySyncPayload(payload);
    markSyncedTo(payload.updatedAt, payload, "pull");
    setSyncStatus("ok", "Синхронизировано: " + new Date().toLocaleTimeString().slice(0, 5));
    return true;
  } catch (e) {
    setSyncStatus("err", "Не удалось загрузить: " + e.message);
    return false;
  }
}

// Отправляет данные на сервер. ПЕРЕД отправкой проверяет: не сохранил ли
// кто-то (например, вы же с другого устройства) более новую версию данных
// с момента, когда мы в последний раз читали сервер. Если сохранил — не
// затираем её молча, а показываем пользователю модалку с выбором.
async function pushToGistNow() {
  const { token, gistId } = getSyncConfig();
  if (!token) return;
  if (syncInFlight) {
    // Отправка уже идёт (например, только что стартовала по таймеру), а тут
    // подоспело ещё одно изменение. Раньше это изменение просто терялось —
    // теперь запоминаем и досылаем сразу же, как только текущая отправка
    // завершится (см. finally ниже).
    syncQueued = true;
    return;
  }
  syncInFlight = true;
  setSyncStatus("syncing", "Сохранение на сервер…");
  const payload = buildSyncPayload();
  try {
    if (!gistId) {
      // Гиста ещё нет — создаём первый раз, конфликтовать не с чем.
      const created = await githubGistRequest("POST", "https://api.github.com/gists", token, {
        description: "Учёт деталей — Склад (данные приложения)",
        public: false,
        files: {
          [SYNC_FILENAME]: { content: JSON.stringify(payload) },
          [SYNC_HISTORY_FILENAME]: { content: JSON.stringify(syncHistory) }
        }
      });
      localStorage.setItem(SYNC_GIST_ID_KEY, created.id);
      const gistInput = document.getElementById("syncGistIdInput");
      if (gistInput) gistInput.value = created.id;
      markSyncedTo(payload.updatedAt, payload, "push");
      setSyncStatus("ok", "Синхронизировано: " + new Date().toLocaleTimeString().slice(0, 5));
      return;
    }
    // Сверяем версию на сервере с той, что мы видели в последний раз.
    const remote = await githubGistRequest("GET", "https://api.github.com/gists/" + gistId, token);
    mergeRemoteHistory(remote.files && remote.files[SYNC_HISTORY_FILENAME] && remote.files[SYNC_HISTORY_FILENAME].content);
    const remoteFile = remote.files && remote.files[SYNC_FILENAME];
    const remotePayload = (remoteFile && remoteFile.content) ? JSON.parse(remoteFile.content) : null;
    const lastSynced = getLastSyncedAt();
    const remoteChangedSinceUs = remotePayload && remotePayload.updatedAt && remotePayload.updatedAt !== lastSynced;

    if (remoteChangedSinceUs) {
      if (isPrimaryDevice()) {
        // Главное устройство: не спрашиваем — наша версия побеждает всегда.
        await githubGistRequest("PATCH", "https://api.github.com/gists/" + gistId, token, {
          files: {
            [SYNC_FILENAME]: { content: JSON.stringify(payload) },
            [SYNC_HISTORY_FILENAME]: { content: JSON.stringify(syncHistory) }
          }
        });
        markSyncedTo(payload.updatedAt, payload, "push");
        setSyncStatus("ok", "Синхронизировано (главное устройство): " + new Date().toLocaleTimeString().slice(0, 5));
        return;
      } else {
        // Подчинённое устройство: не спрашиваем — молча берём версию с сервера.
        applyingRemote = true;
        try {
          applySyncPayload(remotePayload);
        } finally {
          applyingRemote = false;
        }
        markSyncedTo(remotePayload.updatedAt, remotePayload, "pull");
        setSyncStatus("ok", "Обновлено с сервера (автоматически): " + new Date().toLocaleTimeString().slice(0, 5));
        return;
      }
    }

    await githubGistRequest("PATCH", "https://api.github.com/gists/" + gistId, token, {
      files: {
        [SYNC_FILENAME]: { content: JSON.stringify(payload) },
        [SYNC_HISTORY_FILENAME]: { content: JSON.stringify(syncHistory) }
      }
    });
    markSyncedTo(payload.updatedAt, payload, "push");
    setSyncStatus("ok", "Синхронизировано: " + new Date().toLocaleTimeString().slice(0, 5));
  } catch (e) {
    setSyncStatus("err", "Не удалось сохранить: " + e.message);
  } finally {
    syncInFlight = false;
    // Пока мы отправляли этот запрос, пришло ещё одно изменение — досылаем
    // его сейчас же (но не тогда, когда одновременно открыта модалка
    // конфликта: сначала пусть пользователь решит, что делать с текущим).
    if (syncQueued && !pendingConflict) {
      syncQueued = false;
      pushToGistNow();
    }
  }
}

// Показывает модалку "на сервере более новые данные" и ждёт решения пользователя.
function showSyncConflict(remotePayload, localPayload) {
  pendingConflict = { remotePayload, localPayload };
  setSyncStatus("err", "Конфликт: на сервере есть более новые данные — выберите вариант (⚙)");
  document.getElementById("syncConflictOverlay").classList.add("open");
}
function closeSyncConflict() {
  document.getElementById("syncConflictOverlay").classList.remove("open");
}
document.getElementById("syncConflictTakeRemote").addEventListener("click", () => {
  if (!pendingConflict) return;
  applySyncPayload(pendingConflict.remotePayload);
  markSyncedTo(pendingConflict.remotePayload.updatedAt, pendingConflict.remotePayload, "pull");
  setSyncStatus("ok", "Загружена версия с сервера: " + new Date().toLocaleTimeString().slice(0, 5));
  pendingConflict = null;
  closeSyncConflict();
});
document.getElementById("syncConflictKeepLocal").addEventListener("click", async () => {
  if (!pendingConflict) return;
  const { token, gistId } = getSyncConfig();
  const payload = buildSyncPayload(); // берём самые свежие данные, а не снимок на момент конфликта
  pendingConflict = null;
  closeSyncConflict();
  try {
    setSyncStatus("syncing", "Сохранение вашей версии…");
    await githubGistRequest("PATCH", "https://api.github.com/gists/" + gistId, token, {
      files: {
        [SYNC_FILENAME]: { content: JSON.stringify(payload) },
        [SYNC_HISTORY_FILENAME]: { content: JSON.stringify(syncHistory) }
      }
    });
    markSyncedTo(payload.updatedAt, payload, "push");
    setSyncStatus("ok", "Синхронизировано: " + new Date().toLocaleTimeString().slice(0, 5));
  } catch (e) {
    setSyncStatus("err", "Не удалось сохранить: " + e.message);
  }
});
document.getElementById("syncConflictLater").addEventListener("click", () => {
  pendingConflict = null;
  closeSyncConflict();
});

function scheduleSync() {
  if (applyingRemote) return;          // это мы сами только что применили данные с сервера
  markLocalChange();                   // запоминаем: на этом устройстве есть свежая правка
  if (!isSyncConfigured()) return;
  if (syncTimer) clearTimeout(syncTimer);
  syncTimer = setTimeout(() => { syncTimer = null; pushToGistNow(); }, SYNC_DEBOUNCE_MS);
}

// Немедленно (без ожидания debounce) пытается отправить несохранённые правки.
// Используется, когда пользователь сворачивает/закрывает вкладку — лучше
// попытаться отправить сразу, чем ждать и потерять правки.
function flushSyncNow() {
  if (!isSyncConfigured()) return;
  if (!isDirty()) return;
  if (syncTimer) { clearTimeout(syncTimer); syncTimer = null; }
  if (!syncInFlight) pushToGistNow();
}
document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "hidden") {
    flushSyncNow();
  } else if (document.visibilityState === "visible") {
    // Возврат в приложение: если не открыто ни одной модалки — тихо
    // подтягиваем актуальную версию с сервера. Подчинённое устройство делает
    // это всегда (даже если у него остались свои правки — сервер главнее),
    // главное — только если у него самого нет неотправленных правок.
    const modalOpen = document.querySelector(".modal-overlay.open");
    if (isSyncConfigured() && !syncInFlight && !modalOpen) {
      if (!isPrimaryDevice() || !isDirty()) pullFromGist(true);
    }
  }
});
window.addEventListener("pagehide", flushSyncNow);

// Подчинённое устройство само периодически проверяет сервер, пока страница
// открыта — чтобы обновления с главного устройства подтягивались без
// необходимости сворачивать/открывать вкладку заново.
function setupSecondaryPolling() {
  if (secondaryPollTimer) { clearInterval(secondaryPollTimer); secondaryPollTimer = null; }
  if (!isSyncConfigured() || isPrimaryDevice()) return;
  secondaryPollTimer = setInterval(() => {
    if (document.visibilityState !== "visible") return;
    if (syncInFlight || applyingRemote) return;
    const modalOpen = document.querySelector(".modal-overlay.open");
    if (modalOpen) return;
    pullFromGist(true);
  }, SECONDARY_POLL_MS);
}

function openSyncModal() {
  const { token, gistId } = getSyncConfig();
  document.getElementById("syncTokenInput").value = token;
  document.getElementById("syncGistIdInput").value = gistId;
  document.getElementById("syncPrimaryToggle").checked = isPrimaryDevice();
  document.getElementById("syncOverlay").classList.add("open");
}
function closeSyncModal() {
  document.getElementById("syncOverlay").classList.remove("open");
}
(function setupSyncBtnPress() {
  const btn = document.getElementById("syncBtn");
  let timer = null, longFired = false, startX = 0, startY = 0;
  function clearTimer() { if (timer) { clearTimeout(timer); timer = null; } }
  btn.addEventListener("pointerdown", (e) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    longFired = false;
    startX = e.clientX; startY = e.clientY;
    clearTimer();
    timer = setTimeout(() => {
      longFired = true; timer = null;
      if (navigator.vibrate) navigator.vibrate(15);
      openSyncModalGated();
    }, LONG_PRESS_MS);
  });
  btn.addEventListener("pointermove", (e) => {
    if (!timer) return;
    if (Math.abs(e.clientX - startX) > LONG_PRESS_MOVE_TOLERANCE || Math.abs(e.clientY - startY) > LONG_PRESS_MOVE_TOLERANCE) clearTimer();
  });
  btn.addEventListener("pointerup", () => {
    const hadTimer = !!timer;
    clearTimer();
    if (hadTimer && !longFired) quickSyncAction();
  });
  btn.addEventListener("pointercancel", clearTimer);
  btn.addEventListener("contextmenu", (e) => e.preventDefault());
})();
document.getElementById("syncPwBtn").addEventListener("click", changeSyncPassword);
document.getElementById("syncClose").addEventListener("click", closeSyncModal);
document.getElementById("syncOverlay").addEventListener("click", (e) => {
  if (e.target.id === "syncOverlay") closeSyncModal();
});
document.getElementById("syncPrimaryToggle").addEventListener("change", (e) => {
  localStorage.setItem(SYNC_PRIMARY_KEY, e.target.checked ? "1" : "0");
  setupSecondaryPolling();
  updateGuestModeUI();
});
document.getElementById("syncSaveBtn").addEventListener("click", async () => {
  const token = document.getElementById("syncTokenInput").value.trim();
  const gistId = document.getElementById("syncGistIdInput").value.trim();
  if (!token) { alert("Укажите токен."); return; }
  localStorage.setItem(SYNC_TOKEN_KEY, token);
  if (gistId) localStorage.setItem(SYNC_GIST_ID_KEY, gistId);
  else localStorage.removeItem(SYNC_GIST_ID_KEY);
  // Если на этом устройстве есть несохранённые правки (например, только что
  // добавили позицию) — ни в коем случае не тянем данные с сервера первым
  // делом, это молча стёрло бы их. Раньше именно так и происходило: указан
  // gistId → сразу pullFromGist() поверх свежих локальных изменений.
  // Теперь: есть несохранённые правки → отправляем их (push сам покажет
  // модалку выбора, если на сервере тем временем что-то ещё изменилось).
  // Нечего терять (uже всё синхронизировано или это первое подключение
  // к существующему Gist) → можно спокойно подтянуть версию с сервера.
  if (gistId && !isDirty()) {
    const ok = await pullFromGist();
    if (!ok) await pushToGistNow();
  } else {
    await pushToGistNow();
  }
  setupSecondaryPolling();
  updateGuestModeUI();
});
document.getElementById("syncPullBtn").addEventListener("click", () => pullFromGist());
document.getElementById("syncHistoryBtn").addEventListener("click", () => {
  renderSyncHistory();
  document.getElementById("syncHistoryOverlay").classList.add("open");
});
document.getElementById("syncHistoryClose").addEventListener("click", () => {
  document.getElementById("syncHistoryOverlay").classList.remove("open");
});
document.getElementById("syncHistoryOverlay").addEventListener("click", (e) => {
  if (e.target.id === "syncHistoryOverlay") document.getElementById("syncHistoryOverlay").classList.remove("open");
});
document.getElementById("syncForgetBtn").addEventListener("click", () => {
  if (!confirm("Отключить синхронизацию на этом устройстве? Токен и ID Gist будут забыты (сами данные в Gist останутся).")) return;
  localStorage.removeItem(SYNC_TOKEN_KEY);
  localStorage.removeItem(SYNC_GIST_ID_KEY);
  localStorage.removeItem(SYNC_PRIMARY_KEY);
  document.getElementById("syncTokenInput").value = "";
  document.getElementById("syncGistIdInput").value = "";
  document.getElementById("syncPrimaryToggle").checked = false;
  setSyncStatus("off", "Не настроено");
  updateDirtyIndicator();
  setupSecondaryPolling();
  updateGuestModeUI();
});

/* ==================== Выпадающее меню действий (⋮) — Экспорт/История ==================== */
document.getElementById("headMenuBtn").addEventListener("click", (e) => {
  e.stopPropagation();
  document.getElementById("headMenuPanel").classList.toggle("open");
});
document.querySelectorAll("#headMenuPanel button").forEach((btn) => {
  btn.addEventListener("click", () => document.getElementById("headMenuPanel").classList.remove("open"));
});
document.addEventListener("click", (e) => {
  const panel = document.getElementById("headMenuPanel");
  if (!panel.classList.contains("open")) return;
  if (e.target.closest("#headMenuPanel") || e.target.closest("#headMenuBtn")) return;
  panel.classList.remove("open");
});

/* ==================== Старт ==================== */
renderAll();
renderWarehouseAll();
renderOneCAll();

updateDirtyIndicator();
if (isSyncConfigured()) {
  if (!isPrimaryDevice()) {
    // Подчинённое устройство: сервер всегда главнее — просто подтягиваем.
    setSyncStatus("syncing", "Загрузка с сервера…");
    pullFromGist();
  } else if (isDirty()) {
    // На этом устройстве остались правки, которые не успели уйти на сервер
    // в прошлый раз (например, вкладку закрыли слишком быстро). Раньше в
    // этом месте всегда делался pullFromGist(), который бы их молча стёр —
    // теперь сначала пробуем их отправить (с проверкой конфликтов внутри).
    setSyncStatus("syncing", "Отправляем несохранённые изменения…");
    pushToGistNow();
  } else {
    setSyncStatus("syncing", "Загрузка с сервера…");
    pullFromGist();
  }
} else {
  setSyncStatus("off", "Не настроено. Нажмите на ⚙, чтобы включить синхронизацию.");
}
setupSecondaryPolling();
updateGuestModeUI();

/* ==================== Поля количества: авто-ширина + курсор в конец ====================
   Ширина поля растёт вслед за введённым числом (не обрезает 1000+), а при
   тапе по уже заполненному полю курсор сразу встаёт после последней цифры. */
const QTY_INPUT_SELECTOR = ".countInput, .whQtyInput, .ocQtyInput";
function autoSizeQtyInput(input) {
  const len = String(input.value || "").length;
  input.style.width = Math.max(len + 1.4, 2.4) + "ch";
}
document.addEventListener("input", (e) => {
  const input = e.target.closest(QTY_INPUT_SELECTOR);
  if (!input) return;
  autoSizeQtyInput(input);
});
document.addEventListener("focus", (e) => {
  const input = e.target.closest(QTY_INPUT_SELECTOR);
  if (!input) return;
  autoSizeQtyInput(input);
  const end = input.value.length;
  setTimeout(() => { try { input.setSelectionRange(end, end); } catch (err) {} }, 0);
}, true);
document.querySelectorAll(QTY_INPUT_SELECTOR).forEach(autoSizeQtyInput);
new MutationObserver((mutations) => {
  mutations.forEach((m) => {
    m.addedNodes.forEach((node) => {
      if (node.nodeType !== 1) return;
      if (node.matches && node.matches(QTY_INPUT_SELECTOR)) autoSizeQtyInput(node);
      if (node.querySelectorAll) node.querySelectorAll(QTY_INPUT_SELECTOR).forEach(autoSizeQtyInput);
    });
  });
}).observe(document.body, { childList: true, subtree: true });

/* ==================== Копирование кода товара по одному тапу ====================
   Один тап (или клик на ПК) на код детали/расходника сразу копирует его
   в буфер обмена — без выделения и без "—" у пустых значений. */
function copyCodeText(span) {
  if (!span) return;
  const text = span.getAttribute("data-code") || span.textContent || "";
  if (!text) return;
  const done = () => {
    span.classList.add("code-copied");
    setTimeout(() => span.classList.remove("code-copied"), 450);
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done).catch(() => {
      fallbackCopy(text);
      done();
    });
  } else {
    fallbackCopy(text);
    done();
  }
}
function fallbackCopy(text) {
  const ta = document.createElement("textarea");
  ta.value = text;
  ta.style.position = "fixed";
  ta.style.opacity = "0";
  document.body.appendChild(ta);
  ta.select();
  try { document.execCommand("copy"); } catch (e) {}
  document.body.removeChild(ta);
}
document.addEventListener("click", (e) => {
  const span = e.target.closest(".code-text");
  if (!span) return;
  copyCodeText(span);
});


/* ==================== PWA: регистрация service worker ====================
   Нужно для установки на главный экран телефона и офлайн-работы.
   Работает только при открытии по https (или через GitHub Pages) —
   на file:// service worker браузером не регистрируется, но это не мешает
   основной работе программы, просто эта функция не активируется. */
if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("sw.js").catch(() => {});
  });
}
